package com.mannvaasam.controller;
import com.mannvaasam.model.Cart; import com.mannvaasam.service.CartService; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/cart") public class CartController { final CartService s; public CartController(CartService s){this.s=s;} @GetMapping public Cart get(){return s.get();} @PostMapping("/items") public Cart add(@RequestBody Map<String,Object> b){return s.add(((Number)b.get("productId")).longValue(),((Number)b.getOrDefault("quantity",1)).intValue());} @PutMapping("/items/{id}") public Cart update(@PathVariable Long id,@RequestBody Map<String,Object> b){return s.update(id,((Number)b.get("quantity")).intValue());} @DeleteMapping("/items/{id}") public Cart remove(@PathVariable Long id){return s.remove(id);} @DeleteMapping public Map<String,String> clear(){s.clear();return Map.of("message","Cart cleared");} }